function toggleSidebar(){const n=document.querySelector(".sidebar"),t=document.querySelector(".main-container"),i=window.innerWidth<=768;if(!i){n.classList.toggle("sidebar--collapsed");t.classList.toggle("main-container--expanded");n.classList.remove("sidebar--mobile-open");const i=n.classList.contains("sidebar--collapsed");localStorage.setItem("sidebarCollapsed",i)}}function toggleMobileSidebar(){const n=document.querySelector(".sidebar"),t=window.innerWidth<=768;t&&(n.classList.toggle("sidebar--mobile-open"),n.classList.remove("sidebar--collapsed"))}function toggleSubmenu(n,t){n.preventDefault();const r=window.innerWidth<=768;let i;t==="profile"?i=document.querySelector(".sidebar__menu-item--profile"):t==="users"&&(i=document.querySelector(".sidebar__menu-item--users"));i&&(r||t==="users")&&!document.querySelector(".sidebar").classList.contains("sidebar--collapsed")&&i.classList.toggle(t==="profile"?"sidebar__menu-item--profile--active":"sidebar__menu-item--users--active")}document.addEventListener("DOMContentLoaded",function(){const n=document.querySelector(".sidebar"),t=document.querySelector(".main-container"),i=localStorage.getItem("sidebarCollapsed")==="true";i&&window.innerWidth>768?(n.classList.add("sidebar--collapsed"),t.classList.add("main-container--expanded")):(n.classList.remove("sidebar--collapsed"),t.classList.remove("main-container--expanded"));document.documentElement.classList.remove("sidebar-initial-collapsed")});